function binarySearch(arr: number[], target: number): number {
  let l = 0, r = arr.length - 1;
  while (l <= r) {
    const mid = l + Math.floor((r - l) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) l = mid + 1;
    else r = mid - 1;
  }
  return -1;
}

function twoSumSorted(arr: number[], target: number): [number, number] | null {
  let l = 0, r = arr.length - 1;
  while (l < r) {
    const sum = arr[l] + arr[r];
    if (sum === target) return [l, r];
    if (sum < target) l++; else r--;
  }
  return null;
}

function minSubArrayLen(target: number, nums: number[]): number {
  let l = 0, sum = 0, minLen = Infinity;
  for (let r = 0; r < nums.length; r++) {
    sum += nums[r];
    while (sum >= target) {
      minLen = Math.min(minLen, r - l + 1);
      sum -= nums[l++];
    }
  }
  return minLen === Infinity ? 0 : minLen;
}

function nextGreaterElements(nums: number[]): number[] {
  const res = new Array(nums.length).fill(-1);
  const stack: number[] = []; // stores indices
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[i] > nums[stack[stack.length - 1]]) {
      const idx = stack.pop()!;
      res[idx] = nums[i];
    }
    stack.push(i);
  }
  return res;
}

class TrieNode {
  children: Map<string, TrieNode> = new Map();
  isEnd = false;
}
class Trie {
  root = new TrieNode();
  insert(word: string) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch)!;
    }
    node.isEnd = true;
  }
}

function topoSort(numCourses: number, prereqs: [number, number][]): number[] {
  const inDegree = new Array(numCourses).fill(0);
  const adj: number[][] = Array.from({ length: numCourses }, () => []);
  for (const [v, u] of prereqs) { adj[u].push(v); inDegree[v]++; }
  const q = inDegree.map((d, i) => d === 0 ? i : -1).filter(i => i !== -1);
  const order: number[] = [];
  while (q.length) {
    const node = q.shift()!;
    order.push(node);
    for (const neighbor of adj[node]) if (--inDegree[neighbor] === 0) q.push(neighbor);
  }
  return order.length === numCourses ? order : [];
}

class DSU {
  parent: number[];
  constructor(n: number) {
    this.parent = Array.from({ length: n }, (_, i) => i);
  }
  find(i: number): number {
    if (this.parent[i] === i) return i;
    return (this.parent[i] = this.find(this.parent[i])); // Path compression
  }
  union(i: number, j: number): boolean {
    const rootI = this.find(i), rootJ = this.find(j);
    if (rootI === rootJ) return false;
    this.parent[rootI] = rootJ;
    return true;
  }
}
